-- R-058/R-069/R-071/R-093/R-094/R-099. Fresh private validation schemas only.
ALTER TABLE _dg_native_asset_origins DROP CONSTRAINT native_asset_source_kind;
ALTER TABLE _dg_native_asset_origins ADD CONSTRAINT native_asset_source_kind CHECK(source_kind IN('private_upload','package_import','video_upload','system_speech','media_processing','recording','ae_media','live_recording','character_source'));
CREATE TABLE _dg_native_character_sources(
 asset_id text PRIMARY KEY REFERENCES assets(id),upload_id text NOT NULL REFERENCES uploads(id),initial_consent_id text NOT NULL REFERENCES consents(id),
 kind text NOT NULL CHECK(kind IN('puppet2d','mannequin3d','uploaded_glb')),media_type text NOT NULL,
 sha256 text NOT NULL CHECK(sha256 ~ '^[a-f0-9]{64}$'),size bigint NOT NULL CHECK(size BETWEEN 1 AND 8388608),specs text NOT NULL,
 synthetic bigint NOT NULL CHECK(synthetic IN(0,1)),configuration text,actor_id text NOT NULL REFERENCES users(id),created_at text NOT NULL,
 CHECK((kind='puppet2d' AND media_type='application/vnd.digitalguide.puppet+json' AND synthetic=1 AND size<=4096 AND configuration IS NOT NULL)
 OR(kind='mannequin3d' AND media_type='model/gltf-binary' AND synthetic=1 AND configuration IS NOT NULL)
 OR(kind='uploaded_glb' AND media_type='model/gltf-binary' AND synthetic=0 AND configuration IS NULL))
);
CREATE TRIGGER native_character_source_immutable BEFORE UPDATE OR DELETE ON _dg_native_character_sources FOR EACH ROW EXECUTE FUNCTION dg_native_append_only();
CREATE TRIGGER native_character_version_immutable BEFORE UPDATE OR DELETE ON studio_character_versions FOR EACH ROW EXECUTE FUNCTION dg_native_append_only();
ALTER TABLE studio_characters ADD CONSTRAINT native_character_shape CHECK(environment='mock' AND app_env IN('development','sandbox') AND version>0 AND archived IN(0,1) AND source_version>0 AND source_sha256 ~ '^[a-f0-9]{64}$' AND kind IN('photo','video','illustration2d','model3d') AND visual_style IN('realistic','cartoon') AND char_length(name) BETWEEN 1 AND 80 AND char_length(note)<=400 AND char_length(costume_label)<=80 AND char_length(pose_label)<=80);
CREATE FUNCTION dg_native_character_source_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE a assets%ROWTYPE;u uploads%ROWTYPE;o _dg_native_asset_origins%ROWTYPE;c consents%ROWTYPE;v jsonb;
BEGIN
 SELECT * INTO a FROM assets WHERE id=NEW.asset_id;SELECT * INTO u FROM uploads WHERE id=NEW.upload_id;SELECT * INTO o FROM _dg_native_asset_origins WHERE asset_id=NEW.asset_id;SELECT * INTO c FROM consents WHERE id=NEW.initial_consent_id;
 IF a.id IS NULL OR u.id IS NULL OR o.asset_id IS NULL OR c.id IS NULL OR a.upload_id<>u.id OR a.tenant_id<>u.tenant_id OR a.workspace_id<>u.workspace_id OR a.category<>'avatar' OR a.synthetic<>NEW.synthetic OR o.source_kind<>'character_source' OR o.upload_id<>u.id OR o.sha256<>NEW.sha256 OR o.size<>NEW.size OR o.tenant_id<>a.tenant_id OR o.workspace_id<>a.workspace_id OR o.environment<>'mock' OR o.app_env<>(SELECT app_env FROM _dg_native_runtime_control WHERE id=1) OR u.owner_id<>NEW.actor_id OR u.media_type<>NEW.media_type OR u.sha256<>NEW.sha256 OR u.size<>NEW.size OR u.specs::jsonb IS DISTINCT FROM NEW.specs::jsonb OR c.asset_id<>a.id OR c.tenant_id<>a.tenant_id OR c.workspace_id<>a.workspace_id OR c.purpose<>'character_use' OR c.revoked_at IS NOT NULL OR c.expires_at<=dg_utc_now() THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Character source must match its immutable private object, original actor and independent consent';END IF;
 IF NEW.configuration IS NOT NULL THEN v:=NEW.configuration::jsonb;IF NOT coalesce(v->>'format'='digitalguide-puppet' AND v->>'version'='1' AND v->>'outfit' IN('suit','apron','casual') AND v->>'pose' IN('standing','seated') AND v->>'bodyColor' ~ '^#[0-9a-fA-F]{6}$' AND v->>'accentColor' ~ '^#[0-9a-fA-F]{6}$' AND v->>'faceColor' ~ '^#[0-9a-fA-F]{6}$' AND(SELECT count(*) FROM jsonb_object_keys(v))=7,false) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Original character configuration must match its fixed format';END IF;END IF;
 IF NEW.kind='puppet2d' AND(NEW.specs::jsonb IS DISTINCT FROM '{"width":512,"height":768,"rigVersion":1}'::jsonb OR NEW.sha256<>encode(sha256(convert_to(NEW.configuration,'UTF8')),'hex') OR NEW.size<>octet_length(NEW.configuration)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Original puppet source must contain its exact fixed configuration bytes';END IF;RETURN NEW;
END $dg$;
CREATE TRIGGER native_character_source_guard BEFORE INSERT ON _dg_native_character_sources FOR EACH ROW EXECUTE FUNCTION dg_native_character_source_guard();
CREATE FUNCTION dg_native_character_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE a assets%ROWTYPE;u uploads%ROWTYPE;c consents%ROWTYPE;parent studio_characters%ROWTYPE;parent_id text;depth integer:=0;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Character history cannot be deleted';END IF;
 IF TG_OP='INSERT' THEN IF NEW.version<>1 OR NEW.archived<>0 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Character starts with version one and is not archived';END IF;
 ELSIF to_jsonb(NEW)-ARRAY['name','kind','visual_style','source_asset_id','source_version','source_sha256','consent_id','parent_id','costume_label','pose_label','expires_at','note','version','archived','updated_at'] IS DISTINCT FROM to_jsonb(OLD)-ARRAY['name','kind','visual_style','source_asset_id','source_version','source_sha256','consent_id','parent_id','costume_label','pose_label','expires_at','note','version','archived','updated_at'] OR NEW.version<>OLD.version+1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Character scope is fixed and edits require exactly one new version';END IF;
 -- Archiving is still possible when the original source has expired or been withdrawn.
 IF TG_OP='UPDATE' AND NEW.archived=1 AND to_jsonb(NEW)-ARRAY['archived','version','updated_at'] IS NOT DISTINCT FROM to_jsonb(OLD)-ARRAY['archived','version','updated_at'] THEN RETURN NEW;END IF;
 SELECT * INTO a FROM assets WHERE id=NEW.source_asset_id;SELECT * INTO u FROM uploads WHERE id=a.upload_id;SELECT * INTO c FROM consents WHERE id=NEW.consent_id;
 IF a.id IS NULL OR u.id IS NULL OR c.id IS NULL OR a.tenant_id<>NEW.tenant_id OR a.workspace_id<>NEW.workspace_id OR a.archived<>0 OR a.version<>NEW.source_version OR u.sha256<>NEW.source_sha256 OR a.expires_at<=dg_utc_now() OR a.expires_at<NEW.expires_at OR c.asset_id<>a.id OR c.tenant_id<>NEW.tenant_id OR c.workspace_id<>NEW.workspace_id OR c.purpose<>'character_use' OR c.revoked_at IS NOT NULL OR c.expires_at<NEW.expires_at OR NEW.expires_at<=dg_utc_now() OR NOT EXISTS(SELECT 1 FROM _dg_native_asset_origins o WHERE o.asset_id=a.id AND o.upload_id=u.id AND o.tenant_id=a.tenant_id AND o.workspace_id=a.workspace_id AND o.sha256=u.sha256 AND o.size=u.size AND o.environment=NEW.environment AND o.app_env=NEW.app_env) OR EXISTS(SELECT 1 FROM character_derivations WHERE asset_id=a.id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Character requires the current scoped original source and independent valid consent';END IF;
 IF NOT coalesce((NEW.kind='photo' AND u.media_type='image/png') OR(NEW.kind='video' AND u.media_type='video/mp4') OR(NEW.kind='illustration2d' AND(u.media_type='image/png' OR(u.media_type='application/vnd.digitalguide.puppet+json' AND NEW.visual_style='cartoon'))) OR(NEW.kind='model3d' AND u.media_type='model/gltf-binary'),false) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Character kind and original file type must match';END IF;
 parent_id:=NEW.parent_id;WHILE parent_id IS NOT NULL LOOP depth:=depth+1;SELECT * INTO parent FROM studio_characters WHERE id=parent_id;IF parent.id IS NULL OR parent.id=NEW.id OR depth>20 OR parent.tenant_id<>NEW.tenant_id OR parent.workspace_id<>NEW.workspace_id OR parent.environment<>NEW.environment OR parent.app_env<>NEW.app_env OR parent.kind<>NEW.kind THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Character variants must stay in scope without cycles';END IF;parent_id:=parent.parent_id;END LOOP;RETURN NEW;
END $dg$;
CREATE TRIGGER native_character_guard BEFORE INSERT OR UPDATE OR DELETE ON studio_characters FOR EACH ROW EXECUTE FUNCTION dg_native_character_guard();
CREATE FUNCTION dg_native_character_history_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE c studio_characters%ROWTYPE;v jsonb:=NEW.payload::jsonb;
BEGIN SELECT * INTO c FROM studio_characters WHERE id=NEW.character_id;
 IF c.id IS NULL OR NEW.version<>c.version OR v->>'id' IS DISTINCT FROM c.id OR v->>'workspaceId' IS DISTINCT FROM c.workspace_id OR v->>'name' IS DISTINCT FROM c.name OR v->>'kind' IS DISTINCT FROM c.kind OR v->>'visualStyle' IS DISTINCT FROM c.visual_style OR v->>'sourceAssetId' IS DISTINCT FROM c.source_asset_id OR(v->>'sourceVersion')::bigint IS DISTINCT FROM c.source_version OR v->>'consentId' IS DISTINCT FROM c.consent_id OR v->>'parentId' IS DISTINCT FROM c.parent_id OR v->>'costumeLabel' IS DISTINCT FROM c.costume_label OR v->>'poseLabel' IS DISTINCT FROM c.pose_label OR v->>'expiresAt' IS DISTINCT FROM c.expires_at OR v->>'note' IS DISTINCT FROM c.note OR(v->>'version')::bigint IS DISTINCT FROM c.version OR(v->>'archived')::boolean IS DISTINCT FROM(c.archived=1) OR v->>'updatedAt' IS DISTINCT FROM c.updated_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Character history must contain the exact current catalog version';END IF;RETURN NEW;
END $dg$;
CREATE TRIGGER native_character_history_guard BEFORE INSERT ON studio_character_versions FOR EACH ROW EXECUTE FUNCTION dg_native_character_history_guard();
CREATE FUNCTION dg_native_character_history_deferred() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
BEGIN IF NOT EXISTS(SELECT 1 FROM studio_character_versions WHERE character_id=NEW.id AND version=NEW.version) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Character edit and immutable history must commit together';END IF;RETURN NULL;END $dg$;
CREATE CONSTRAINT TRIGGER native_character_history_deferred AFTER INSERT OR UPDATE ON studio_characters DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION dg_native_character_history_deferred();
CREATE FUNCTION dg_native_live_puppet_snapshot_valid(v jsonb,tenant text,workspace text,environment text,app text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE b jsonb:=v->'puppet'->'binding';c studio_characters%ROWTYPE;a assets%ROWTYPE;u uploads%ROWTYPE;r consents%ROWTYPE;source _dg_native_character_sources%ROWTYPE;
BEGIN
 IF NOT(v->'settings' ? 'puppet') THEN RETURN NOT(v ? 'puppet');END IF;
 IF NOT coalesce(b IS NOT NULL AND v->'speech' IS NOT NULL AND v->'settings'->>'speechPlanId'=v->'speech'->>'planId' AND v->'settings'->'puppet'->>'placement' IN('left','right') AND b->>'renderer'='digitalguide-puppet-rms-v1',false) THEN RETURN false;END IF;
 SELECT * INTO c FROM studio_characters WHERE id=b->>'characterId';SELECT * INTO a FROM assets WHERE id=c.source_asset_id;SELECT * INTO u FROM uploads WHERE id=a.upload_id;SELECT * INTO r FROM consents WHERE id=c.consent_id;SELECT * INTO source FROM _dg_native_character_sources WHERE asset_id=a.id;
 RETURN coalesce(c.id IS NOT NULL AND a.id IS NOT NULL AND u.id IS NOT NULL AND r.id IS NOT NULL AND source.asset_id IS NOT NULL AND c.tenant_id=tenant AND c.workspace_id=workspace AND c.environment=environment AND c.app_env=app AND c.kind='illustration2d' AND c.visual_style='cartoon' AND c.archived=0 AND c.version=(b->>'characterVersion')::bigint AND c.name=b->>'name' AND c.source_asset_id=b->>'sourceAssetId' AND c.source_version=(b->>'sourceVersion')::bigint AND c.source_sha256=b->>'sourceSHA256' AND c.consent_id=b->>'consentId' AND c.id=v->'settings'->'puppet'->>'characterId' AND c.version=(v->'settings'->'puppet'->>'characterVersion')::bigint AND a.tenant_id=tenant AND a.workspace_id=workspace AND a.version=c.source_version AND a.archived=0 AND a.synthetic=1 AND u.media_type='application/vnd.digitalguide.puppet+json' AND u.sha256=c.source_sha256 AND u.size=(b->>'sourceSize')::bigint AND u.size BETWEEN 1 AND 4096 AND r.tenant_id=tenant AND r.workspace_id=workspace AND r.asset_id=a.id AND r.purpose='character_use' AND r.revoked_at IS NULL AND source.kind='puppet2d' AND source.upload_id=u.id AND source.sha256=u.sha256 AND source.configuration::jsonb=v->'puppet'->'configuration' AND b->>'expiresAt'>dg_utc_now() AND b->>'expiresAt'=least(c.expires_at,r.expires_at,a.expires_at),false);
EXCEPTION WHEN data_exception THEN RETURN false;
END $dg$;
CREATE FUNCTION dg_native_output_puppet_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
BEGIN IF NOT dg_native_live_puppet_snapshot_valid(NEW.snapshot::jsonb,NEW.tenant_id,NEW.workspace_id,NEW.environment,NEW.app_env) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Live puppet requires exact fixed character, source, consent and explicit real speech binding';END IF;RETURN NEW;END $dg$;
CREATE TRIGGER native_output_puppet_guard BEFORE INSERT ON live_outputs FOR EACH ROW EXECUTE FUNCTION dg_native_output_puppet_guard();
CREATE FUNCTION dg_native_live_puppet_invalidate() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
BEGIN
 IF TG_TABLE_NAME='studio_characters' THEN UPDATE live_outputs SET invalidated_at=dg_utc_now(),invalidation_reason='本场固定二维角色已更新或归档，旧输出及派生用途不恢复。',version=version+1,updated_at=dg_utc_now() WHERE invalidated_at IS NULL AND snapshot::jsonb->'puppet'->'binding'->>'characterId'=OLD.id;
 ELSIF TG_TABLE_NAME='assets' THEN UPDATE live_outputs SET invalidated_at=dg_utc_now(),invalidation_reason='本场二维角色原件已更新或归档，旧输出及派生用途不恢复。',version=version+1,updated_at=dg_utc_now() WHERE invalidated_at IS NULL AND snapshot::jsonb->'puppet'->'binding'->>'sourceAssetId'=OLD.id;
 ELSIF NEW.revoked_at IS NOT NULL THEN UPDATE live_outputs SET invalidated_at=dg_utc_now(),invalidation_reason='本场二维角色独立使用授权已撤回，含角色的媒体及派生用途受限。',version=version+1,updated_at=dg_utc_now() WHERE invalidated_at IS NULL AND snapshot::jsonb->'puppet'->'binding'->>'consentId'=OLD.id;
 END IF;RETURN NULL;
END $dg$;
CREATE TRIGGER native_live_puppet_character_invalidate AFTER UPDATE ON studio_characters FOR EACH ROW EXECUTE FUNCTION dg_native_live_puppet_invalidate();
CREATE TRIGGER native_live_puppet_asset_invalidate AFTER UPDATE ON assets FOR EACH ROW EXECUTE FUNCTION dg_native_live_puppet_invalidate();
CREATE TRIGGER native_live_puppet_consent_invalidate AFTER UPDATE ON consents FOR EACH ROW EXECUTE FUNCTION dg_native_live_puppet_invalidate();
REVOKE ALL ON FUNCTION dg_native_character_source_guard(),dg_native_character_guard(),dg_native_character_history_guard(),dg_native_character_history_deferred(),dg_native_live_puppet_snapshot_valid(jsonb,text,text,text,text),dg_native_output_puppet_guard(),dg_native_live_puppet_invalidate() FROM PUBLIC;
